mapper.insert:
BEGIN
DELETE T_ECC_ROLE_EMP_REL WHERE ROLE_ID = #{sp.roleId} AND EMP_ID = #{empId}; INSERT INTO T_ECC_ROLE_EMP_REL ( ROLE_ID, EMP_ID, STAT, CREATE_ID, CREATE_TIME, MODIFY_ID, MODIFY_TIME )VALUES( #{sp.roleId}, #{empId}, 'C', #{sp.createId}, SYSDATE, #{sp.createId}, SYSDATE );
END;

mapper.select:
SELECT ROLE_ID,EMP_ID FROM T_ECC_ROLE_EMP_REL 
WHERE STAT ='C' 
AND EMP_ID= #{empId}

SELECT TO_CHAR(WM_CONCAT(EMP_ID)) FROM ( SELECT DISTINCT EMP_ID FROM T_ECC_ROLE_EMP_REL WHERE ROLE_ID IN
#{roleVo.roleId}
)

SELECT WRER.ROLE_ID, WRER.EMP_ID, WRER.STAT, WRER.CREATE_ID, WRER.CREATE_TIME, WRER.MODIFY_ID, WRER.MODIFY_TIME, (SELECT TE.EMPEMAIL FROM T_ECC_EMPLOYEEE TE WHERE TE.EMPID = WRER.EMP_ID) ATTR1 FROM T_ECC_ROLE_EMP_REL WRER LEFT JOIN T_ECC_ROLE WR ON WRER.ROLE_ID = WR.ROLE_ID WHERE 1 = 1 AND WRER.STAT = 'C'
AND WR.ROLE_NAME = #{sp.roleName}
AND WR.ROLE_ID = #{sp.roleId}
